begin;
-- Real synthetic sessions for member JWT fixtures; rows roll back with this test.
insert into auth.sessions(id,user_id) select md5('pgtap-session:'||id::text)::uuid,id from auth.users;
set local search_path=extensions,public,private;
select no_plan();
select ok(not has_table_privilege('authenticated','private.voice_admissions','select'),'voice admissions remain private');
select ok(not has_function_privilege('authenticated','public.voice_service(text,uuid,jsonb)','execute'),'member cannot invoke reconciliation or acknowledge removal');
select ok(not has_function_privilege('anon','public.group_voice_access(uuid,text,uuid,uuid)','execute'),'anonymous voice denied');
select ok(has_function_privilege('service_role','public.voice_service(text,uuid,jsonb)','execute'),'trusted worker can reconcile');
insert into auth.sessions(id,user_id) values
 ('96000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001'),
 ('96000000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000002'),
 ('96000000-0000-4000-8000-000000000003','10000000-0000-0000-0000-000000000003');
insert into public.groups(id,owner_id,name) values('96000000-0000-4000-8000-000000000010','10000000-0000-0000-0000-000000000001','Voice test');
insert into public.group_members(group_id,profile_id,role,status) values
 ('96000000-0000-4000-8000-000000000010','10000000-0000-0000-0000-000000000001','owner','active'),
 ('96000000-0000-4000-8000-000000000010','10000000-0000-0000-0000-000000000002','member','active'),
 ('96000000-0000-4000-8000-000000000010','10000000-0000-0000-0000-000000000003','member','invited');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid))::text,true);
select set_config('request.jwt.claims','{"session_id":"96000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.group_voice_access('96000000-0000-4000-8000-000000000010','join')$$,'42501','voice_access_denied','disabled capability refuses transport admission');
reset role;
update private.launch_capabilities set voice=true;
set local role authenticated;
select throws_ok($$select public.group_voice_access('96000000-0000-4000-8000-000000000010','join')$$,'55000','voice_worker_unavailable','no worker heartbeat means no new calls');
reset role;
select is(public.voice_service('healthy'),'true'::jsonb,'healthy worker enables join gate');
set local role authenticated;
select set_config('test.voice_owner',public.group_voice_access('96000000-0000-4000-8000-000000000010','join')::text,true);
select is(current_setting('test.voice_owner')::jsonb->>'role','owner','room role comes from current group membership');
select is(public.list_groups()->0->>'isVoiceActive','true','group list shows authorized live voice presence');
select ok((current_setting('test.voice_owner')::jsonb->>'admissionId')::uuid<>'10000000-0000-0000-0000-000000000001','opaque provider identity does not expose account ID');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000003','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000003')::uuid))::text,true);
select set_config('request.jwt.claims','{"session_id":"96000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.group_voice_access('96000000-0000-4000-8000-000000000010','join')$$,'42501','voice_access_denied','pending invite cannot hear the group');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid))::text,true);
select set_config('request.jwt.claims','{"session_id":"96000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('test.voice_member',public.group_voice_access('96000000-0000-4000-8000-000000000010','join')::text,true);
select is(current_setting('test.voice_member')::jsonb->>'roomName',current_setting('test.voice_owner')::jsonb->>'roomName','authorized group members share one room');
select throws_ok($$select public.group_voice_access('96000000-0000-4000-8000-000000000010','heartbeat',(current_setting('test.voice_owner')::jsonb->>'admissionId')::uuid)$$,'42501','voice_access_denied','member cannot renew another account admission');
select throws_ok($$select public.group_voice_access('96000000-0000-4000-8000-000000000010','remove',null,'10000000-0000-0000-0000-000000000001')$$,'42501','voice_moderator_required','member cannot remove room owner');
select throws_ok($$select public.group_voice_access('96000000-0000-4000-8000-000000000010','end')$$,'42501','voice_moderator_required','member cannot end another person call');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid))::text,true);
select set_config('request.jwt.claims','{"session_id":"96000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.group_voice_access('96000000-0000-4000-8000-000000000010','remove',null,'10000000-0000-0000-0000-000000000002')$$,'owner removes participant');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid))::text,true);
select set_config('request.jwt.claims','{"session_id":"96000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.group_voice_access('96000000-0000-4000-8000-000000000010','join')$$,'42501','voice_removed_for_call','removed participant cannot get a new identity in this call');
reset role;
select is(public.voice_service('validate',(current_setting('test.voice_member')::jsonb->>'admissionId')::uuid),'false'::jsonb,'removed admission immediately invalid in DB');
select is(public.voice_service('validate',(current_setting('test.voice_owner')::jsonb->>'admissionId')::uuid,'{"roomName":"group-other"}'),'false'::jsonb,'valid admission cannot authorize a different provider room');
select is(jsonb_array_length(public.voice_service('reconcile')->'revocations'),1,'provider removal is durable before acknowledgement');
select is(public.voice_service('healthy'),'false'::jsonb,'unfinished provider removal cannot report healthy');
select is(public.voice_service('revoked',(current_setting('test.voice_member')::jsonb->>'admissionId')::uuid),'true'::jsonb,'worker acknowledges provider removal');
select is(public.voice_service('healthy'),'true'::jsonb,'drained queue may report health');
insert into public.blocks(blocker_id,blocked_id) values('10000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001');
select is(public.voice_service('validate',(current_setting('test.voice_owner')::jsonb->>'admissionId')::uuid),'false'::jsonb,'reverse-direction block revokes existing admission');
select is(jsonb_array_length(public.voice_service('reconcile')->'revocations'),1,'block queues remaining participant removal independently of client');
select is(jsonb_array_length(public.voice_service('reconcile')->'rooms'),1,'room ends when no valid admissions remain');
select lives_ok($$select public.voice_service('revoked',(current_setting('test.voice_owner')::jsonb->>'admissionId')::uuid)$$,'provider removal acknowledged');
select lives_ok($$select public.voice_service('deleted',substring(current_setting('test.voice_owner')::jsonb->>'roomName' from 7)::uuid)$$,'room deletion acknowledged');
delete from public.blocks where blocker_id='10000000-0000-0000-0000-000000000002';
select is(public.voice_service('healthy'),'true'::jsonb,'worker healthy after room cleanup');
set local role authenticated;
select set_config('test.voice_member2',public.group_voice_access('96000000-0000-4000-8000-000000000010','join')::text,true);
select isnt(current_setting('test.voice_member2')::jsonb->>'admissionId',current_setting('test.voice_member')::jsonb->>'admissionId','later call cannot reuse prior provider identity');
reset role;
delete from auth.sessions where id='96000000-0000-4000-8000-000000000002';
select is(public.voice_service('validate',(current_setting('test.voice_member2')::jsonb->>'admissionId')::uuid),'false'::jsonb,'revoked auth session invalidates still-unexpired voice token');
set local role authenticated;
select throws_ok($$select public.group_voice_access('96000000-0000-4000-8000-000000000010','heartbeat',(current_setting('test.voice_member2')::jsonb->>'admissionId')::uuid)$$,'42501','voice_session_required','unexpired JWT cannot renew after session deletion');
reset role;
select public.voice_service('reconcile');
select public.voice_service('revoked',(current_setting('test.voice_member2')::jsonb->>'admissionId')::uuid);
select public.voice_service('deleted',substring(current_setting('test.voice_member2')::jsonb->>'roomName' from 7)::uuid);
select public.voice_service('healthy');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid))::text,true);
select set_config('request.jwt.claims','{"session_id":"96000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('test.voice_owner2',public.group_voice_access('96000000-0000-4000-8000-000000000010','join')::text,true);
reset role;
update private.voice_admissions set valid_until=now()-interval '1 second' where id=(current_setting('test.voice_owner2')::jsonb->>'admissionId')::uuid;
select is(public.voice_service('validate',(current_setting('test.voice_owner2')::jsonb->>'admissionId')::uuid),'false'::jsonb,'lost client heartbeat expires admission');
select is(jsonb_array_length(public.voice_service('reconcile')->'revocations'),1,'abandoned call queued for forced provider removal');
select is(public.voice_service('webhook',null,jsonb_build_object('id','voice-test-retry','event','participant_left','roomName',current_setting('test.voice_owner2')::jsonb->>'roomName','identity',current_setting('test.voice_owner2')::jsonb->>'admissionId'))->>'duplicate','false','first signed event recorded');
select is(public.voice_service('webhook',null,jsonb_build_object('id','voice-test-retry','event','participant_left'))->>'duplicate','true','webhook retry deduplicated');
select public.voice_service('revoked',(current_setting('test.voice_owner2')::jsonb->>'admissionId')::uuid);
select public.voice_service('deleted',substring(current_setting('test.voice_owner2')::jsonb->>'roomName' from 7)::uuid);
select public.voice_service('healthy');
set local role authenticated;
select set_config('test.voice_owner3',public.group_voice_access('96000000-0000-4000-8000-000000000010','join')::text,true);
reset role;
update public.profiles set deletion_requested_at=now() where id='10000000-0000-0000-0000-000000000001';
select is(public.voice_service('validate',(current_setting('test.voice_owner3')::jsonb->>'admissionId')::uuid),'false'::jsonb,'account deletion request revokes voice before auth user cleanup');
delete from public.groups where id='96000000-0000-4000-8000-000000000010';
select is(jsonb_array_length(public.voice_service('reconcile')->'revocations'),1,'deleting group preserves provider removal tombstone');
select ok(exists(select 1 from private.voice_admissions where id=(current_setting('test.voice_owner3')::jsonb->>'admissionId')::uuid),'unacknowledged provider removal survives destructive local deletion');
select * from finish();
rollback;

